//! The closed color palette (docs/palette.json). Every color the game shows
//! comes from these swatches; spell effects are the only exemption. The
//! constants are generated by `node scripts/palette.mjs`; do not edit them by
//! hand. Engine-free so the client and offline texture tools share it.

mod swatches;
pub use swatches::*;

/// One palette color, stored as 8-bit sRGB `0xRRGGBB`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Swatch {
    pub id: &'static str,
    pub rgb: u32,
}

impl Swatch {
    pub const fn new(id: &'static str, rgb: u32) -> Self {
        Self { id, rgb }
    }

    /// sRGB channels in 0..=1.
    pub const fn srgb(self) -> [f32; 3] {
        [
            ((self.rgb >> 16) & 0xff) as f32 / 255.0,
            ((self.rgb >> 8) & 0xff) as f32 / 255.0,
            (self.rgb & 0xff) as f32 / 255.0,
        ]
    }

    /// `#rrggbb`, as written in the palette file.
    pub fn hex(self) -> String {
        format!("#{:06x}", self.rgb)
    }
}

/// Looks a swatch up by its palette id.
pub fn by_id(id: &str) -> Option<Swatch> {
    ALL.iter().copied().find(|swatch| swatch.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_constants_match_the_palette_file() {
        let spec: serde_json::Value =
            serde_json::from_str(include_str!("../../../docs/palette.json")).unwrap();
        let listed: Vec<(String, String)> = spec["families"]
            .as_array()
            .unwrap()
            .iter()
            .flat_map(|family| family["swatches"].as_array().unwrap())
            .map(|s| {
                (
                    s["id"].as_str().unwrap().to_owned(),
                    s["hex"].as_str().unwrap().to_owned(),
                )
            })
            .collect();
        let generated: Vec<(String, String)> = ALL
            .iter()
            .map(|swatch| (swatch.id.to_owned(), swatch.hex()))
            .collect();
        assert_eq!(
            generated, listed,
            "run `node scripts/palette.mjs` after editing docs/palette.json"
        );
    }

    #[test]
    fn channels_decode_from_hex() {
        let swatch = Swatch::new("test-1", 0xff_80_00);
        assert_eq!(swatch.srgb(), [1.0, 128.0 / 255.0, 0.0]);
        assert_eq!(swatch.hex(), "#ff8000");
        assert_eq!(by_id("night-1"), Some(NIGHT_1));
        assert_eq!(by_id("nope"), None);
    }
}
